--
-- Name: create_session(bigint, integer, timestamp without time zone, numeric); Type: FUNCTION; Schema: public; Owner: AK
--

CREATE FUNCTION public.create_session(p_film_id bigint, p_hall_id integer, p_session_time timestamp without time zone, p_price numeric) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_session_id INT;
    hall_is_busy INT;
BEGIN
    SELECT 1 INTO hall_is_busy
    FROM public.sessions s
    JOIN public.session_hall sh ON s.id = sh.session_id
    WHERE sh.hall_id = p_hall_id AND s.date = p_session_time;

    IF hall_is_busy = 1 THEN
        RAISE EXCEPTION 'Зал % уже занят в %', p_hall_id, p_session_time;
    END IF;

    VALUES (p_film_id, p_session_time, p_price)
    RETURNING id INTO new_session_id;

    VALUES (new_session_id, p_hall_id);

    RETURN new_session_id;
END;
$$;


ALTER FUNCTION public.create_session(p_film_id bigint, p_hall_id integer, p_session_time timestamp without time zone, p_price numeric) OWNER TO "AK";

