--
-- Name: generate_customers(integer); Type: FUNCTION; Schema: public; Owner: AK
--

CREATE FUNCTION public.generate_customers(count integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    i INT;
    random_name TEXT;
    random_phone TEXT;
BEGIN
    FOR i IN 1..count LOOP
        random_name := (
            SELECT string_agg(substr('abcdefghijklmnopqrstuvwxyz', floor(random() * 26)::int + 1, 1), '')
            FROM generate_series(1, 10)
        );
        random_phone := (
            SELECT string_agg(floor(random() * 10)::int::text, '')
            FROM generate_series(1, 10)
        );
        VALUES (random_name, random_phone);
    END LOOP;
END;
$$;


